use std::collections::HashMap;
use std::env;
use std::fs;
use std::process;

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() < 2 {
        eprintln!("usage: {} <file>", args[0]);
        process::exit(1);
    }
    let content = fs::read_to_string(&args[1]).unwrap_or_else(|e| {
        eprintln!("error reading {}: {}", args[1], e);
        process::exit(1);
    });

    // Track insertion order with a sequence number
    let mut store: HashMap<String, (usize, String)> = HashMap::new(); // key -> (order, value)
    let mut order_counter: usize = 0;

    for (line_num, line) in content.lines().enumerate() {
        let line = line.trim();
        if line.is_empty() {
            continue;
        }

        let parts: Vec<&str> = line.splitn(3, '|').collect();
        if parts.len() < 2 {
            eprintln!("malformed record at line {}: '{}'", line_num + 1, line);
            process::exit(1);
        }

        match parts[0] {
            "put" => {
                if parts.len() < 3 {
                    eprintln!("malformed put record at line {}: '{}'", line_num + 1, line);
                    process::exit(1);
                }
                let key = parts[1].to_string();
                let value = parts[2].to_string();
                if let Some(entry) = store.get_mut(&key) {
                    // Update value, keep original order
                    entry.1 = value;
                } else {
                    store.insert(key, (order_counter, value));
                    order_counter += 1;
                }
            }
            "delete" => {
                let key = parts[1];
                store.remove(key);
            }
            other => {
                eprintln!("unknown record kind '{}' at line {}", other, line_num + 1);
                process::exit(1);
            }
        }
    }

    // Sort by insertion order
    let mut entries: Vec<(&String, &(usize, String))> = store.iter().collect();
    entries.sort_by_key(|&(_, &(ord, _))| ord);

    for (key, (_, value)) in entries {
        println!("{}={}", key, value);
    }
}

