            if seen.insert(k.clone()) {
                resolved_keys.push(k.clone());
            }
            resolved_values.insert(k.clone(), sec.values[k].clone());
        }

        for k in &resolved_keys {
            output.push_str(&format!("{}.{}={}\n", sec.name, k, resolved_values[k]));
        }
    }

    print!("{}", output);
