use std::fs;
use std::process;

fn json_escape(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            c if (c as u32) < 0x20 => {
                out.push_str(&format!("\\u{:04x}", c as u32));
            }
            c => out.push(c),
        }
    }
    out
}

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() < 2 {
        eprintln!("usage: {} <file>", args[0]);
        process::exit(1);
    }
    let content = fs::read_to_string(&args[1]).unwrap_or_else(|e| {
        eprintln!("error reading {}: {}", args[1], e);
        process::exit(1);
    });

    let mut name: Option<String> = None;
    let mut count: Option<i64> = None;
    let mut note: Option<String> = None;

    for line in content.lines() {
        let line = line.trim();
        if line.is_empty() {
            continue;
        }
        // Split on first tab
        if let Some(tab_pos) = line.find('\t') {
            let key = &line[..tab_pos];
            let val = &line[tab_pos+1..];
            match key {
                "name" => name = Some(val.to_string()),
                "count" => {
                    count = Some(val.parse::<i64>().unwrap_or_else(|_| {
                        eprintln!("invalid count: '{}'", val);
                        process::exit(1);
                    }));
                }
                "note" => note = Some(val.to_string()),
                other => {
                    eprintln!("unknown field: '{}'", other);
                    process::exit(1);
                }
            }
        }
    }

    let count = count.unwrap_or_else(|| {
        eprintln!("missing field: count");
        process::exit(1);
    });
    let name = name.unwrap_or_else(|| {
        eprintln!("missing field: name");
        process::exit(1);
    });
    let note = note.unwrap_or_else(|| {
        eprintln!("missing field: note");
        process::exit(1);
    });

    // Output JSON with exact key order: count, name, note
    println!(
        "{{\"count\":{},\"name\":\"{}\",\"note\":\"{}\"}}",
        count,
        json_escape(&name),
        json_escape(&note)
    );
}
